class Pair<T, V> {
    private T data1;
    private V data2;

    public void setValue(T dt1, V dt2) {
        data1 = dt1;
        data2 = dt2;
    }

    public T getT1Value() { return data1; }
    public V getT2Value() { return data2; }
}

Pair<Integer, String> p = new Pair<>();
p.setValue(1, "One");
